mapper.select:
SELECT h.currency_code, (SELECT CURRENCY_NAME FROM fnd_currency WHERE CURRENCY_CODE =h.currency_code )AS currency_code_n, (SELECT CURRENCY_NAME FROM fnd_currency WHERE CURRENCY_CODE =h.currency_code )AS currency_name, h.report_year as rpt_date, (select concat(concat(concat(h.fiscal_year,'-'),h.fiscal_month),'-01') from dual) as rpt_date_n, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9130%'),0) AS total_assets, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9117%'),0) AS fixed_assets, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9161%'),0) AS net_assets, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9153%'),0) AS total_liabilities, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9100%'),0) AS currency_finance, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9115%'),0) AS long_due_amount, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A147%'),0) AS principal_income, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A146%'),0) AS flow_rate, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A148%'),0) AS service_income, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'PROFIT_STATEMENT' AND l.account_code LIKE '%H9171%'),0) AS operating_cost, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'PROFIT_STATEMENT' AND l.account_code LIKE '%H9170%'),0) AS income, nvl((SELECT sum(nvl(l.final_amount, 0)) FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'PROFIT_STATEMENT' AND l.account_code in ('H9174', 'H9175', 'H9176')),0) AS business_cost,
nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'PROFIT_STATEMENT' AND l.account_code LIKE '%H9186%'),0) AS net_profit, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'CASH_FLOW_STATEMENT' AND l.account_code LIKE '%H9208%'),0) AS net_operating_cashflow, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'CASH_FLOW_STATEMENT' AND l.account_code LIKE '%H9220%'),0) AS invest_operating_cashflow, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'CASH_FLOW_STATEMENT' AND l.account_code LIKE '%H9231%'),0) AS fund_operating_cashflow, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'CASH_FLOW_STATEMENT' AND l.account_code LIKE '%H9254%'),0) AS net_cashflow, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'BALANCE_SHEET' AND l.account_code LIKE '%G9154%'),0) AS registered_capital, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'PROFIT_STATEMENT' AND l.account_code LIKE '%H9170%'),0) AS business_income, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A145%'),0) AS assets_liabilities, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A153%'),0) AS ol, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A155%'),0) AS roa, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A156%'),0) AS roe, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A157%'),0) AS sales_growth_rate, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'INCOME_STATEMENT' AND l.account_code LIKE '%H9180%'),0) AS operating_profit, nvl((SELECT l.final_amount FROM hls_fin_statement_ln l WHERE l.fin_statement_hd_id = h.fin_statement_hd_id AND l.line_type = 'FINANCIAL_INDEX' AND l.account_code LIKE '%A163%'),0) AS repayment_ratio, h.fin_statement_hd_id FROM hls_fin_statement_hd h
h.fiscal_year is not null
and h.bp_id = #{bpId}
and h.fin_statement_hd_id = #{finStatementHdId}
